package cn.iocoder.yudao.module.zsjos.service.review; import cn.iocoder.yudao.module.zsjos.dal.mysql.review.ReviewReportMapper; import cn.iocoder.yudao.module.zsjos.framework.permission.ZsjosObjectPermissionProvider; import jakarta.annotation.Resource; import org.springframework.stereotype.Component; import java.util.Objects; @Component public class ReviewObjectPermissionProvider implements ZsjosObjectPermissionProvider { @Resource private ReviewReportMapper mapper; public String getBizType(){return "media-review";} public boolean hasPermission(Long id,String action,Long uid){var x=mapper.selectById(id);if(x==null)return false;if("approve".equals(action)||"reject".equals(action))return Objects.equals(x.getReviewerUserId(),uid);return Objects.equals(x.getAuthorUserId(),uid)||Objects.equals(x.getReviewerUserId(),uid);} }
